import {GROUPS,CHARACTER_FIELDS,SCENE_FIELDS} from './catalog.mjs';
export const PLAN_LIMITS={characters:6,scenes:6,shots:8,idea:6000};
export const PLAN_CHAR_KEYS=CHARACTER_FIELDS.map(x=>x[0]);
export const PLAN_SCENE_KEYS=[...SCENE_FIELDS.map(x=>x[0]),'time','weather','lightSource','lightDirection','lightQuality','lightNote'];
export const PLAN_CAMERA_KEYS=['framing','angle','composition','move','speed','stability','lens','focus','direction','orbit','start','end'];
export const PLAN_COMMERCE_KEYS=['name','category','material','color','audience','sellingPoints','evidence','goal','platform','scene','lighting','composition','camera','hook','cta','copy'];
export function planCatalog(){return Object.fromEntries(['look','medium','genre','color','texture','framing','angle','composition','move','speed','stability','lens','focus','time','weather','lightSource','lightDirection','lightQuality','emotion','negative'].map(k=>[k,GROUPS[k].options.map(x=>({id:x.id,label:x.label}))]));}
const planString={type:'string'};
const planObject=properties=>({type:'object',properties,required:Object.keys(properties),additionalProperties:false});
const planStrings=keys=>Object.fromEntries(keys.map(k=>[k,planString]));
const planEnum=k=>({type:'string',enum:['',...GROUPS[k].options.map(x=>x.id)]});
export function planSchema(){
 const camera=planObject(Object.fromEntries(PLAN_CAMERA_KEYS.map(k=>[k,k==='orbit'?{type:'number',minimum:0,maximum:360}:k==='direction'?{type:'string',enum:['','cw','ccw']}:GROUPS[k]?planEnum(k):planString])));
 const character=planObject({ref:planString,...planStrings(PLAN_CHAR_KEYS)});
 const scene=planObject({ref:planString,...Object.fromEntries(PLAN_SCENE_KEYS.map(k=>[k,GROUPS[k]?planEnum(k):planString]))});
 const shot=planObject({title:planString,duration:{type:'number',minimum:0.5,maximum:60},characterRefs:{type:'array',items:planString,maxItems:6},sceneRef:planString,action:planString,startState:planString,endState:planString,dialogue:planString,audio:planString,emotion:planEnum('emotion'),camera});
 return planObject({title:planString,logline:planString,style:planObject({look:planEnum('look'),medium:planEnum('medium'),genre:planEnum('genre'),color:planEnum('color'),texture:{type:'array',items:planEnum('texture')},custom:planString}),negativePrompts:{type:'array',items:planEnum('negative')},characters:{type:'array',items:character,maxItems:6},scenes:{type:'array',items:scene,maxItems:6},shots:{type:'array',items:shot,maxItems:8},commerce:planObject({...planStrings(PLAN_COMMERCE_KEYS),beats:{type:'array',items:planObject({title:planString,start:{type:'number'},end:{type:'number'},action:planString,voice:planString})}})});
}
export function normalizePlan(raw){
 const fail=msg=>{throw Error('填写方案无效：'+msg);};
 const walk=(x,depth=0)=>{if(depth>12)fail('层级过深');if(x&&typeof x==='object')for(const k of Object.keys(x)){if(['__proto__','prototype','constructor'].includes(k))fail('包含不允许的字段');walk(x[k],depth+1);}};walk(raw);
 if(!raw||typeof raw!=='object'||Array.isArray(raw))fail('需要结构化对象');
 const text=(x,max=1200)=>{if(x==null)return '';if(typeof x!=='string'||x.length>max)fail('文字类型或长度不正确');return x.trim();};
 const list=(x,max)=>{if(x==null)return [];if(!Array.isArray(x)||x.length>max)fail('列表超出限制');return x;};
 const choice=(key,x)=>{const value=text(x,80);if(value&&!GROUPS[key].options.some(v=>v.id===value))fail('未知选项 '+key);return value;};
 const refs=new Set(),sceneRefs=new Set();
 const characters=list(raw.characters,PLAN_LIMITS.characters).map(c=>{if(!c||typeof c!=='object')fail('角色格式错误');const out={ref:text(c.ref,80),...Object.fromEntries(PLAN_CHAR_KEYS.map(k=>[k,text(c[k],400)]))};if(!out.ref||!out.name||refs.has(out.ref))fail('角色标识或名称缺失/重复');refs.add(out.ref);return out;});
 const scenes=list(raw.scenes,PLAN_LIMITS.scenes).map(s=>{if(!s||typeof s!=='object')fail('场景格式错误');const out={ref:text(s.ref,80),...Object.fromEntries(PLAN_SCENE_KEYS.map(k=>[k,GROUPS[k]?choice(k,s[k]):text(s[k],600)]))};if(!out.ref||!out.name||sceneRefs.has(out.ref))fail('场景标识或名称缺失/重复');sceneRefs.add(out.ref);return out;});
 const shots=list(raw.shots,PLAN_LIMITS.shots).map(s=>{if(!s||typeof s!=='object')fail('分镜格式错误');const duration=Number(s.duration);if(!Number.isFinite(duration)||duration<.5||duration>60)fail('单镜时长应为0.5—60秒');const ids=list(s.characterRefs,6).map(x=>text(x,80));if(ids.some(x=>!refs.has(x)))fail('分镜引用了未知角色');const sceneRef=text(s.sceneRef,80);if(sceneRef&&!sceneRefs.has(sceneRef))fail('分镜引用了未知场景');const camera={};for(const k of PLAN_CAMERA_KEYS){const value=s.camera?.[k];if(k==='orbit'){if(value!==undefined&&(!Number.isFinite(Number(value))||Number(value)<0||Number(value)>360))fail('环绕角度无效');camera[k]=Number(value)||0;}else camera[k]=GROUPS[k]?choice(k,value):text(value,300);}if(camera.direction&&!['cw','ccw'].includes(camera.direction))fail('运镜方向无效');const action=text(s.action);if(!action)fail('分镜动作不能为空');return {title:text(s.title,120)||'新镜头',duration,characterRefs:[...new Set(ids)],sceneRef,action,...Object.fromEntries(['startState','endState','dialogue','audio'].map(k=>[k,text(s[k])])),emotion:choice('emotion',s.emotion),camera};});
 const style=raw.style||{},commerce=raw.commerce||{};
 const beats=list(commerce.beats,8).map(b=>{const start=Number(b.start),end=Number(b.end);if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start||end>300)fail('广告时间段无效');return {title:text(b.title,120),start,end,action:text(b.action),voice:text(b.voice,500)};});
 const total=shots.reduce((a,s)=>a+s.duration,0);if(total>300)fail('总时长超过300秒');
 return {title:text(raw.title,120),logline:text(raw.logline),style:{...Object.fromEntries(['look','medium','genre','color'].map(k=>[k,choice(k,style[k])])),texture:[...new Set(list(style.texture,10).map(x=>choice('texture',x)).filter(Boolean))],custom:text(style.custom)},negativePrompts:[...new Set(list(raw.negativePrompts,20).map(x=>choice('negative',x)).filter(Boolean))],characters,scenes,shots,commerce:{...Object.fromEntries(PLAN_COMMERCE_KEYS.map(k=>[k,text(commerce[k])])),beats}};
}
export function normalizePlanRequest(raw){if(!raw||typeof raw!=='object')throw Error('请求格式不正确');const idea=String(raw.idea||'').trim();if(idea.length<4||idea.length>PLAN_LIMITS.idea)throw Error('请填写4—6000字的创作想法');const duration=Number(raw.duration),shotCount=Number(raw.shotCount);if(!Number.isFinite(duration)||duration<5||duration>120)throw Error('目标时长应在5—120秒');if(!Number.isInteger(shotCount)||shotCount<1||shotCount>8)throw Error('分镜数量应在1—8个');const context=raw.context&&typeof raw.context==='object'?raw.context:{};if(JSON.stringify(context).length>24000)throw Error('当前项目设定过长，请缩减后重试');return {idea,duration,shotCount,mode:raw.mode==='commerce'?'commerce':'story',context};}
export function validateSavedAIData(p){if(p.aiBrief&&(typeof p.aiBrief!=='object'||typeof p.aiBrief.idea!=='string'||p.aiBrief.idea.length>6000||!Number.isFinite(Number(p.aiBrief.duration))||!Number.isFinite(Number(p.aiBrief.shotCount))))throw Error('AI创作想法格式不正确。');if(!p.aiSuggestion)return;const s=p.aiSuggestion,q=s.plan;if(!q||typeof q!=='object'||!['ai','demo'].includes(s.origin)||typeof s.projectId!=='string'||typeof q.title!=='string'||typeof q.logline!=='string')throw Error('AI填写草稿格式不正确。');for(const [k,max] of [['characters',6],['scenes',6],['shots',8]])if(!Array.isArray(q[k])||q[k].length>max||!q[k].every(x=>x&&typeof x==='object'))throw Error('AI填写列表格式不正确。');if(!q.characters.every(c=>typeof c.name==='string')||!q.scenes.every(c=>typeof c.name==='string')||!q.shots.every(x=>typeof x.title==='string'&&typeof x.action==='string'&&Number.isFinite(Number(x.duration))))throw Error('AI分镜草稿格式不正确。');}
